const IDENT_RE = /^[A-Za-z0-9_.\/:-]+$/
const INT_RE = /^(0|[1-9][0-9]*)$/

export class LineError extends Error {}

export function isIdent(value) {
  return IDENT_RE.test(value)
}

/**
 * Parses an unsigned decimal integer field, enforcing the minimum the
 * grammar assigns to that field name. Throws LineError with the exact
 * `<field> must be an integer of at least <least>` message on any failure,
 * whether the text isn't a valid integer or the value is below the minimum.
 */
export function parseIntField(field, value, least) {
  if (!INT_RE.test(value)) {
    throw new LineError(`${field} must be an integer of at least ${least}`)
  }
  const n = BigInt(value)
  if (n < BigInt(least)) {
    throw new LineError(`${field} must be an integer of at least ${least}`)
  }
  return n
}
"}

