{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e7-attempts-5-t5-20260919T163704Z/cell-lAFGWa/src/policies.js","content":"/**
 * Per-key state for the two policy kinds. Each policy tracks one state
 * object per key, created lazily the first time that key reaches it.
 */

/**
 * A token bucket. Tokens are tracked as integer "units" equal to tokens
 * times `per`, so refilling by `refill` tokens per `per` ticks over `n`
 * ticks is the exact integer `refill * n`, with no rounding ever needed.
 */
export class TokenBucket {
  constructor(capacity, refill, per) {
    this.capacity = capacity
    this.refill = refill
    this.per = per
    this.capUnits = capacity * per
    this.states = new Map()
  }

  #stateFor(key, tick) {
    let s = this.states.get(key)
    if (!s) {
      s = { units: this.capUnits, lastTick: tick }
      this.states.set(key, s)
    }
    return s
  }

  advance(key, tick) {
    const s = this.#stateFor(key, tick)
    const delta = tick - s.lastTick
    if (delta > 0n) {
      s.units += this.refill * delta
      if (s.units > this.capUnits) s.units = this.capUnits
      s.lastTick = tick
    }
  }

  allows(key) {
    const s = this.states.get(key)
    return s.units >= this.per
  }

  record(key) {
    const s = this.states.get(key)
    s.units -= this.per
  }
}

/** A sliding window. Remembered ticks are kept in increasing order. */
export class SlidingWindow {
  constructor(limit, span) {
    this.limit = limit
    this.span = span
    this.states = new Map()
  }

  #stateFor(key) {
    let s = this.states.get(key)
    if (!s) {
      s = { ticks: [] }
      this.states.set(key, s)
    }
    return s
  }

  advance(key, tick) {
    const s = this.#stateFor(key)
    const threshold = tick - this.span
    let i = 0
    while (i < s.ticks.length && s.ticks[i] <= threshold) i++
    if (i > 0) s.ticks.splice(0, i)
  }

  allows(key) {
    const s = this.states.get(key)
    return BigInt(s.ticks.length) < this.limit
  }

  record(key, tick) {
    const s = this.states.get(key)
    s.ticks.push(tick)
  }
}
"}

