{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/e7-attempts-5-t5-20260919T163704Z/cell-lAFGWa/src/engine.js","content":"/**
 * Parses a limiter file and replays its events, producing the ordered list
 * of verdicts that both `replay` and `summary` are formatted from.
 */

import { LineError, isIdent, parseIntField } from './validate.js'
import { TokenBucket, SlidingWindow } from './policies.js'

/** Splits stdin into trimmed, comment-and-blank-filtered logical lines. */
function splitLines(text) {
  const raw = text.split('\n')
  if (raw.length > 0 && raw[raw.length - 1] === '') raw.pop()
  return raw
}

/**
 * Runs the whole limiter file and returns its event verdicts.
 * Throws LineError (message only) for the caller to attribute to a line.
 */
export function run(text) {
  const lines = splitLines(text)
  const policies = new Map()
  const routes = [] // { prefix, policyNames }
  const routesByPrefix = new Map()
  let firstEventSeen = false
  let lastTick = null
  const events = [] // { tick, key, allowed, deniedBy }

  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const trimmed = lines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue
    const tokens = trimmed.split(/\s+/)
    const directive = tokens[0]

    try {
      if (directive === 'bucket' || directive === 'window' || directive === 'route') {
        if (firstEventSeen) {
          throw new LineError('declarations must come before the first event')
        }
        if (directive === 'bucket') {
          declareBucket(tokens, policies)
        } else if (directive === 'window') {
          declareWindow(tokens, policies)
        } else {
          declareRoute(tokens, policies, routes, routesByPrefix)
        }
      } else if (directive === 'event') {
        const { tick, key } = parseEvent(tokens)
        if (lastTick !== null && tick < lastTick) {
          throw new LineError(`tick ${tick} is before tick ${lastTick}`)
        }
        lastTick = tick
        firstEventSeen = true
        events.push(applyEvent(tick, key, routes))
      } else {
        throw new LineError(`unknown directive ${directive}`)
      }
    } catch (err) {
      if (err instanceof LineError) {
        throw new LineError(`line ${lineNo}: ${err.message}`)
      }
      throw err
    }
  }

  return events
}

function declareBucket(tokens, policies) {
  if (tokens.length !== 5) {
    throw new LineError('expected bucket <name> <capacity> <refill> <per>')
  }
  const [, name, capacityText, refillText, perText] = tokens
  if (!isIdent(name)) throw new LineError(`invalid policy name ${name}`)
  const capacity = parseIntField('capacity', capacityText, 1)
  const refill = parseIntField('refill', refillText, 0)
  const per = parseIntField('per', perText, 1)
  if (policies.has(name)) throw new LineError(`policy ${name} is declared twice`)
  policies.set(name, new TokenBucket(capacity, refill, per))
}

function declareWindow(tokens, policies) {
  if (tokens.length !== 4) {
    throw new LineError('expected window <name> <limit> <span>')
  }
  const [, name, limitText, spanText] = tokens
  if (!isIdent(name)) throw new LineError(`invalid policy name ${name}`)
  const limit = parseIntField('limit', limitText, 0)
  const span = parseIntField('span', spanText, 1)
  if (policies.has(name)) throw new LineError(`policy ${name} is declared twice`)
  policies.set(name, new SlidingWindow(limit, span))
}

function declareRoute(tokens, policies, routes, routesByPrefix) {
  if (tokens.length < 3) {
    throw new LineError('expected route <prefix> <policy>...')
  }
  const prefix = tokens[1]
  const policyNames = tokens.slice(2)
  if (!isIdent(prefix)) throw new LineError(`invalid route prefix ${prefix}`)
  if (routesByPrefix.has(prefix)) throw new LineError(`prefix ${prefix} is routed twice`)
  for (const name of policyNames) {
    if (!policies.has(name)) throw new LineError(`unknown policy ${name}`)
  }
  const route = { prefix, policyNames }
  routes.push(route)
  routesByPrefix.set(prefix, route)
}

function parseEvent(tokens) {
  if (tokens.length !== 3) {
    throw new LineError('expected event <tick> <key>')
  }
  const [, tickText, key] = tokens
  const tick = parseIntField('tick', tickText, 0)
  if (!isIdent(key)) throw new LineError(`invalid key ${key}`)
  return { tick, key }
}

function findRoute(routes, key) {
  let best = null
  for (const route of routes) {
    if (key.startsWith(route.prefix)) {
      if (!best || route.prefix.length > best.prefix.length) best = route
    }
  }
  return best
}

function applyEvent(tick, key, routes) {
  const route = findRoute(routes, key)
  const policyNames = route ? route.policyNames : []
  const stages = policyNames.map((name) => route.policies.get(name))
