 * verdicts per key.
 */

import { readFileSync } from 'node:fs'
import { LineError } from './validate.js'
import { run } from './engine.js'

function usageError() {
  process.stderr.write('error: usage: cli.js replay|summary\n')
  process.exit(2)
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'replay' && args[0] !== 'summary')) {
    usageError()
    return
  }
  const mode = args[0]
  const input = readFileSync(0, 'utf8')

